<template>
    <div>

        <!-- Veröffentlicht -->
        <button
            v-if="isPublished"
            @click="togglePub"
            title="Veröffentlicht"
            :disabled="loading"
            type="button"
        >
            <svg
                class="w-6 h-6 text-green-500"
                xmlns="http://www.w3.org/2000/svg"
                fill="currentColor"
            >
                <circle cx="12" cy="12" r="10"/>
            </svg>
        </button>

        <!-- Unveröffentlicht -->
        <button
            v-else
            @click="togglePub"
            title="Unveröffentlicht"
            :disabled="loading"
            type="button"
        >
            <svg
                class="w-6 h-6 text-gray-400"
                xmlns="http://www.w3.org/2000/svg"
                fill="currentColor"
            >
                <circle cx="12" cy="12" r="10"/>
            </svg>
        </button>

    </div>
</template>

<script>
import axios from "axios";

export default {

    name: "PublishButton",

    emits: ['update:modelValue'],

    props: {

        table: {
            type: String,
            required: true
        },

        id: {
            type: Number,
            required: true
        },

        modelValue: {
            type: [Number, String],
            default: 0
        },

        public: {
            type: Number,
            default: 0
        }
    },

    data() {

        return {
            loading: false
        };
    },

    computed: {

        isPublished: {

            get() {

                return Number(this.modelValue);
            },

            set(val) {

                this.$emit(
                    'update:modelValue',
                    Number(val)
                );
            }
        }
    },

    methods: {

        async togglePub() {

            if (this.loading) return;

            this.loading = true;

            const newStatus =
                this.isPublished ? 0 : 1;

            try {

                await axios.post('/toggle-pub', {

                    table: this.table,
                    id: this.id,
                    pub: newStatus,
                    public: this.public,
                });

                // SOFORT Parent updaten
                this.isPublished = newStatus;

            } catch (error) {

                console.error(
                    error.response?.data ||
                    error.message
                );

            } finally {

                this.loading = false;
            }
        }
    }
};
</script>
