<template>
    <div v-if="sd == 'ab'">
        <Link :href="routeName" class="flex items-center">
            <div>
                <favicon class="h-10 w-10 mr-2"></favicon>
            </div>
            <div class="flex-col items-start justify-center md:flex">
                <div
                    class="font-logo text-xl lg:text-3xl leading-snug whitespace-nowrap tracking-widest font-bold"
                >
                    <span
                        v-if="brand_1"
                        class="text-primary-sun-500 dark:text-primary-night-500"
                        >{{ brand_1 }}</span
                    >
                    <span
                        v-if="brand_2"
                        class="text-layout-sun-500 dark:text-layout-night-500"
                        >{{ brand_2 }}</span
                    >
                </div>
                <div
                    class="font-title text-xs lg:text-sm leading-snug whitespace-nowrap tracking-wide"
                    v-if="appName"
                >
                    <span> {{ appName }}</span>
                </div>
            </div>
        </Link>
    </div>
    <div v-if="sd == 'mfx'">
        <a href="/"><mfxlogo :ab="'_mfx_alt' + this.GetLogin()"></mfxlogo></a>
    </div>
</template>

<script>
import { Link } from "@inertiajs/vue3";

import Favicon from "@/Application/Components/Logo/Favicon.vue";
import mfxlogo from "@/Application/Shared/mfxlogo.vue";
export default {
    name: "Shared_BrandFooter",

    components: {
        Link,
        Favicon,
        mfxlogo,
    },

    data() {
        return {
            sd: null,
            loginFlag: "",
        };
    },

    mounted() {
        if (typeof window !== "undefined") {
            this.sd = window.subdomain;
            this.loginFlag = this.calcLogin();
        }
    },

    props: {
        routeName: {
            type: String,
            default: "home",
        },
        brand_1: {
            type: String,
            default: "Asarios",
        },
        brand_2: {
            type: String,
            default: "Blog",
        },
        appName: {
            type: String,
            default: null,
        },
    },

    methods: {
        calcLogin() {
            const url = window?.location?.href || "";

            if (
                !url.includes("/login") &&
                !url.includes("/forgot-password") &&
                !url.includes("/register") &&
                !url.includes("/email/verify") &&
                !url.includes("/reset-password") &&
                !url.includes("/confirm-password") &&
                !url.includes("/verify-email")
            ) {
                return "";
            }

            return "l";
        },
        GetLogin()
        {
            const url = location.href;
            if(!url.includes("/login") && !url.includes("/forgot-password") && !url.includes("/register") && !url.includes("/email/verify") && !url.includes("reset-password") && !url.includes("/confirm-password") && !url.includes("/verify-email"))
            {
                return "";
            }
            return "l";
        }

    },
};
</script>

