        <template>
        <layout>
            <MetaHeader :title="ucf(CleanTable()) + ' - Übersicht'" />
        <!-- Header -->
        <template #header>
            <breadcrumb :breadcrumbs="breadcrumbs" :current="tablet"></breadcrumb>
        </template>

        <!-- Table -->
        <section class="mt-8">

            <list-container
            :title="'Tabelle ' + tablez"
            :datarows="{ data: datarows }"
            :route-index="showRoute"
            :xxtable="tableq"
            :filters="filters"
            search-filter="true"
            search-text="Suche nach Inhalten anhand ihres Namens oder ihrer Beschreibung."
            :edit-on="true"
            route-edit="admin.tables.edit"
            :create-on="true"
            :route-create="routeCreate"
            :delete-on="true"
            :pag="pag"
            route-delete="admin.tables.destroy"
            :tableq="this.tableq ?? ''"
            @update-checked-status="onCheckedStatusUpdate"
            >

            <!-- Header-Spalten -->
            <template #header>
                <tr>
                    <th class="np-dl-th-normal lg:hidden">Aktionen</th>
                    <th class="np-dl-th-normal"  v-if="rows?.data?.length && !rows.data[0]?.isNAN && CleanTable()?.trim() !== ''">Drop</th>


                <th class="np-dl-th-normal">ID</th>
                <th class="np-dl-th-normal">Pub</th>
                <th v-if="cat_on_head" class="np-dl-ht-normal">{{ cat_on_head }}</th>
                <th v-if="table_head" class="np-dl-ht-normal">{{ table_head }}</th>
                <th class="np-dl-th-normal">{{ prename }}</th>
                <th class="np-dl-th-normal">{{ predesc }}</th>
                <th v-if="tpart" class="np-dl-th-normal">{{ tpart }}</th>
                <th v-if="table == 'ratings'">{{ imagedesc }}</th>
                <th v-if="aftsetting" class="np-dl-ht-normal">{{ aftsetting }}</th>
                <th class="np-dl-th-normal" v-if="table === 'comments'">Check</th>
                <th class="np-dl-th-normal" v-if="table === 'images'">Beschreibung</th>
                <th class="np-dl-th-normal" v-if="hasCreated">Datum</th>
                <th class="np-dl-th-normal" colspan="2"></th>
                </tr>
            </template>

            <!-- Datenzeilen -->
            <template v-slot:datarow="data">
                <td class="np-dl-td-normal" :draggable="false" @dragstart.prevent @dragstart.prevent.stop>{{ getMixId(data.datarow) }}</td>

                <!-- Pub -->
                <td class="np-dl-td-normal" :draggable="false" v-if="data.datarow.pub !== 'undefined'">
                <PublishButton
                    :table="CleanTable()"
                    :id="data.datarow.id"
                   v-model="data.datarow.pub"
                />
                </td>

                <!-- Kategorie -->
                <td v-if="data.datarow.image_categories" class="np-dl-td-normal"  :draggable="false" @dragstart.prevent @dragstart.prevent.stop>
                <img :src="'/images/_ab/images_categories/sm/' + data.datarow.image_categories + '.jpg'" :title="ucf(data.datarow.image_categories)" :alt="ucf(data.datarow.image_categories)"/>
                </td>
                <td v-if="data.datarow.blog_categories" class="np-dl-td-normal" :draggable="false" @dragstart.prevent @dragstart.prevent.stop>
                <span
                    class="text-sm min-w-fit min-h-fit bg-primary-sun-500 text-primary-sun-900
                        dark:bg-primary-night-500 dark:text-primary-night-900
                        font-semibold px-2.5 py-0.5 rounded-lg whitespace-nowrap"
                >
                    {{ ucf(data.datarow.blog_categories) }}
                </span>
                </td>

                <!-- Projekte -->
                <td v-if="table === 'projects_sheets'" class="np-dl-td-normal break-words whitespace-normal" :draggable="false" @dragstart.prevent @dragstart.prevent.stop>
                {{ ucf(data.datarow.projects) }}
                </td>

                <!-- comments Tabelle -->
                <td v-if="table == 'comments'" class="np-dl-td-normal"  :draggable="false" @dragstart.prevent @dragstart.prevent.stop>
                <CreatedAt :post_id="data.datarow.post_id" :table="data.datarow.admin_table">
                    <span
                    class="text-sm min-w-fit min-h-fit bg-primary-sun-500 text-primary-sun-900
                            dark:bg-primary-night-500 dark:text-primary-night-900
                            font-semibold px-2.5 py-0.5 rounded-lg whitespace-nowrap"
                    >
                    {{ ucf(data.datarow.admin_table) }}

                    </span>
                </CreatedAt>
                </td>

                <!-- Admin Table -->
                <td v-else-if="table != 'comments' && table_head" class="np-dl-td-normal" :draggable="false" @dragstart.prevent @dragstart.prevent.stop>
                <span
                    class="text-sm min-w-fit min-h-fit bg-primary-sun-500 text-primary-sun-900
                        dark:bg-primary-night-500 dark:text-primary-night-900
                        font-semibold px-2.5 py-0.5 rounded-lg whitespace-nowrap"
                >
                    {{ ucf(data.datarow.admin_table) }}
                </span>
                </td>

                <!-- Name -->
                <td class="np-dl-td-normal break-words whitespace-normal max-w-[600px]"  :draggable="false" @dragstart.prevent @dragstart.prevent.stop>
                <span v-html="rumLaut(data.datarow.name)"></span>
                </td>

                <!-- User bei Kommentaren -->
                <td
                class="np-dl-td-normal" :draggable="false" @dragstart.prevent @dragstart.prevent.stop
                v-if="table != 'people' && (users[data.datarow.users_id]?.img || data.datarow.nick || data.datarow.users)"
                >
                <div v-if="users[data.datarow.users_id]?.img && users[data.datarow.users_id].img !== '008.jpg'">
                    <span class="whitespace-nowrap">
                    <img
                        :src="GetProfileImagePath(users[data.datarow.users_id].img)"
                        class="w-[24px] h-[24px] object-cover rounded-full inline"
                    />
                    &nbsp;{{ data.datarow.users }}
                    </span>
                </div>
                <div v-else>
                    <span class="whitespace-nowrap">
                    <img
                        :src="'/images/_' + SD() + '/users/profile_photo_path/008.jpg'"
                        class="max-w-[24px] max-h-[24px] object-cover rounded-full inline"
                    />
                    <span class="inline">&nbsp;&nbsp;{{ data.datarow.nick || data.datarow.users }}</span>
                    </span>
                </div>
                </td>

                <!-- Description -->
                <td
                class="np-dl-td-normal break-words whitespace-normal" :draggable="false" @dragstart.prevent @dragstart.prevent.stop
                v-if="table !== 'comments' && table != 'ratings' && table != 'projects_sheets'"
                >
                <span v-html="rumLaut(data.datarow.description)"></span>
                </td>

                <!-- ratings -->
                <td v-else-if="table === 'ratings'" class="np-dl-td-normal break-words whitespace-normal" :draggable="false" @dragstart.prevent @dragstart.prevent.stop>
                {{ data.datarow.images }}
                </td>
                <td v-if="table === 'ratings'" class="np-dl-td-normal break-words whitespace-normal" :draggable="false" @dragstart.prevent @dragstart.prevent.stop>
                <IconStar
                    v-for="i in data.datarow.rating"
                    :key="i"
                    we="16"
                    he="16"
                    color="#ffa500"
                    class="inline"
                />
                <span class="ml-1">{{ val }}</span>
                </td>

                <!-- Check -->
                <td class="np-dl-td-normal" v-if="table === 'comments'">
                <span
                    v-if="checkedStatus[String(data.datarow.id)] == 1"
                    style="font-size:24px;">
                    ✅
                </span>
                <span v-else class="bg-[rgb(50,174,179)] rounded-full w-[24px] h-[24px] px-[3px] text-white">O</span>

            </td>
            </template>
            </list-container>
            <div class="flex items-center justify-center flex-wrap mt-6 -mb-1 text-xs md:text-base bg-transparent text-layout-sun-700 dark:text-layout-night-700">



    </div>
        </section>
    </layout>
    </template>

<script>
import { defineComponent } from "vue";

import Layout from "@/Application/Admin/Shared/ab/Layout.vue";
import CreatedAt from "@/Application/Components/Form/CreatedAt.vue";
import Breadcrumb from "@/Application/Components/Content/Breadcrumb.vue";
import ListContainer from "@/Application/Components/Lists/ListContainer.vue";

import MetaHeader from "@/Application/Homepage/Shared/MetaHeader.vue";
import PublishButton from "@/Application/Components/Form/PublishButton.vue";
import IconStar from "@/Application/Components/Icons/IconStar.vue";

import {
    CleanTable,
    ucf,
    SD,
    GetSettings,
    rumLaut,
    GetProfileImagePath
} from "@/helpers";

import { router } from '@inertiajs/vue3';

import { route } from 'ziggy-js';

import Sortable from "sortablejs";

import axios from "axios";

let table_z = CleanTable();

let table_alt = table_z;

let table = CleanTable();

export default defineComponent({

    name: "AdminTableShow",

    components: {

        MetaHeader,

        Layout,

        Breadcrumb,

        CreatedAt,

        ListContainer,

        PublishButton,

        IconStar,
    },

    props: {

        applicationName: {

            type: String,

            default:
                "Administrator-Anwendung"
        },

        users: Object,

        pag: [Object, Array],

        table_alt: {

            type: String
        },

        table_q: {

            type: String,

            default: table_alt
        },

        table: {

            type: String,

            required: true
        },

        startPage: {

            type: Boolean,

            default: true
        },

        breadcrumbs: {

            type: Object,

            required: true
        },

        additionalEntries: {

            type: Array,

            default: () => []
        },

        tableq: {

            type: String
        },

        current: {

            type: String,

            required: true
        },

        filters: {

            type: Object,

            default: () => ({})
        },

        rows: {

            type: [Array, Object],

            required: true,

            default: () => []
        },

        datarows: {

            type: [Array, String],

            required: true,

            default: () => []
        },

        itemName_des: {

            type: String,

            default: ""
        },

        formData: {

            type: String,

            default: ""
        },

        thirdparty: String,
    },

    data() {

        return {

            aftsetting: "",

            imagedesc: "Bild",

            searchQuery: "",

            ItemName: "Tabellen",

            tablez: this.ucf(table_z),

            checkedStatus: {},

            sortable: null,

            table:
                CleanTable()
                    .toLowerCase(),

            settings: {},

            namealias: "",

            descalias: "",

            hasCreated: false,

            cat_on_head: "",

            userName: "",

            tablet: "Übersicht",

            localRows:
                this.datarows ?? [],
        };
    },

    computed: {

        tpart() {

            if (this.thirdparty) {

                return this.thirdparty[
                    this.table
                ];
            }

            return false;
        },

        prename() {

            return this.namealias[
                this.table
            ] ?? "Name";
        },

        predesc() {

            return this.descalias[
                this.table
            ] ?? "Beschreibung";
        },

        table_head() {

            return (

                Array.isArray(
                    this.localRows
                )

                &&

                this.localRows[0]
                    ?.admin_table_id

            )

            ||

            typeof this.localRows[0]
                ?.admin_table_id
                !== "undefined"

                ? "Tabelle"

                : "";
        },

        routeCreate() {

            if (!this.tableq)
                return null;

            return route(

                "admin.tables.create",

                this.tableq
            );
        },

        showRoute() {

            return route(

                "admin.tables.show",

                table
            );
        },
    },

    watch: {

        searchValue(newVal) {

            router.get(

                route(

                    'admin.tables.show',

                    this.table_q ?? ''
                ),

                {
                    search:
                        newVal ?? ''
                },

                {
                    preserveState: true,

                    replace: true
                }
            );
        }
    },

    async mounted() {

        this.aftsetting =
            this.aftSET();

        this.cat_on_head =
            this.checkCat();

        this.checkhasCreated();

        this.settings =
            await GetSettings();

        window.settings =
            this.settings;

        if (window.settings?.namealias) {

            this.namealias =
                window.settings.namealias;
        }

        if (window.settings?.descalias) {

            this.descalias =
                window.settings.descalias;
        }

        this.initSortable();

        await this.fetchStatus();

        /*
        |--------------------------------------------------------------------------
        | Mark comments checked on leave/reload
        |--------------------------------------------------------------------------
        */

        if (this.table === 'comments') {

            window.addEventListener(

                'beforeunload',

                this.markCommentsAsChecked
            );
        }
    },
    beforeUnmount() {

        if (this.table === 'comments') {

            window.removeEventListener(

                'beforeunload',

                this.markCommentsAsChecked
            );
        }
    },
    methods: {

        GetProfileImagePath,

        CleanTable,

        ucf,

        SD,

        rumLaut,

        /*
        |--------------------------------------------------------------------------
        | Checked Status
        |--------------------------------------------------------------------------
        */

        isChecked(id) {

            const value =
                this.checkedStatus?.[id];

            return (

                value == 1

                ||

                value === true

                ||

                value === 'true'
            );
        },

        /*
        |--------------------------------------------------------------------------
        | Mark comments checked
        |--------------------------------------------------------------------------
        */

        async markCommentsAsChecked() {

            if (
                !this.localRows
                ||
                !this.localRows.length
            ) {
                return;
            }

            try {

                const ids =
                    this.localRows.map(
                        row => row.id
                    );

                await fetch(

                    '/api/set-comments-checked',

                    {

                        method: 'POST',

                        keepalive: true,

                        headers: {

                            'Content-Type':
                                'application/json',

                            'X-CSRF-TOKEN':

                                document
                                    .querySelector(
                                        'meta[name="csrf-token"]'
                                    )
                                    .content
                        },

                        body: JSON.stringify({

                            ids: ids
                        })
                    }

                );

                /*
                |--------------------------------------------------------------------------
                | Local update
                |--------------------------------------------------------------------------
                */

                ids.forEach(id => {

                    this.checkedStatus[id] = 1;
                });

            } catch (error) {

                console.error(
                    'Fehler beim Speichern:',
                    error
                );
            }
        },

        /*
        |--------------------------------------------------------------------------
        | Remove Item
        |--------------------------------------------------------------------------
        */

        async removeItem() {

            try {

                const response =
                    await axios.get(

                        `/admin/tables/data/${this.table}`
                    );

                this.localRows =
                    response.data.rows;

                this.localRows = [
                    ...this.localRows
                ];

            } catch (error) {

                console.error(

                    "Fehler beim Neuladen der Tabelle:",

                    error
                );
            }
        },

        /*
        |--------------------------------------------------------------------------
        | Sortable
        |--------------------------------------------------------------------------
        */

        initSortable() {

            const tableBody =
                this.$el.querySelector(
                    "tbody"
                );

            if (!tableBody)
                return;

            this.sortable =
                Sortable.create(

                    tableBody,

                    {

                        animation: 150,

                        onEnd: async (
                            evt
                        ) => {

                            const movedItem =
                                this.localRows.splice(

                                    evt.oldIndex,

                                    1
                                )[0];

                            this.localRows.splice(

                                evt.newIndex,

                                0,

                                movedItem
                            );

                            this.localRows = [
                                ...this.localRows
                            ];

                            try {

                                await axios.post(

                                    '/api/save-order/'
                                    + CleanTable(),

                                    {

                                        rows:
                                            this.localRows.map(

                                                (
                                                    row,
                                                    index
                                                ) => ({

                                                    id:
                                                        row.id,

                                                    position:
                                                        index
                                                })
                                            )
                                    }

                                );

                            } catch (error) {

                                console.error(

                                    "Fehler beim Speichern der Reihenfolge:",

                                    error
                                );
                            }
                        },
                    }
                );
        },

        /*
        |--------------------------------------------------------------------------
        | Aft Setting
        |--------------------------------------------------------------------------
        */

        aftSET() {

            if (

                CleanTable()
                    == "shortpoems"

                ||

                CleanTable()
                    == "didyouknow"

                ||

                CleanTable()
                    == "texts"
            ) {

                return "Beschreibung";
            }

            if (
                CleanTable()
                    == "ratings"
            ) {

                return "Sterne";
            }

            if (
                CleanTable()
                    == "projects_sheets"
            ) {

                return "Benutzer";
            }

            return "";
        },

        /*
        |--------------------------------------------------------------------------
        | Checked Status Update
        |--------------------------------------------------------------------------
        */

        onCheckedStatusUpdate(status) {

            // this.checkedStatus = status;
        },

        /*
        |--------------------------------------------------------------------------
        | Fetch Status
        |--------------------------------------------------------------------------
        */

        async fetchStatus() {

            await this.$nextTick();

            if (
                !this.localRows
                ||
                this.localRows.length === 0
            ) {
                return;
            }

            try {

                const response =
                    await axios.get(
                        "/api/chkcom/"
                    );

                this.checkedStatus =
                    response.data.success
                    || {};

                console.log(
                    "CHECK STATUS:",
                    this.checkedStatus
                );

            } catch (error) {

                console.error(

                    "Fehler beim Batch-Status laden:",

                    error
                );
            }
        },

        /*
        |--------------------------------------------------------------------------
        | Mix ID
        |--------------------------------------------------------------------------
        */

        getMixId(row) {

            return this.table !== "comments"

                ? row.id

                : row.post_id;
        },

        /*
        |--------------------------------------------------------------------------
        | Check Category
        |--------------------------------------------------------------------------
        */

        checkCat() {

            let rows;

            if (
                typeof this.localRows
                === "string"
            ) {

                try {

                    rows =
                        JSON.parse(
                            this.localRows
                        );

                } catch (e) {

                    console.error(e);

                    return null;
                }

            } else if (

                Array.isArray(
                    this.localRows
                )

            ) {

                rows =
                    this.localRows;

            } else if (

                typeof this.localRows
                === "object"

            ) {

                rows =
                    Object.values(
                        this.localRows
                    );

            } else {

                return null;
            }

            if (!rows.length)
                return null;

            const hasCategory =
                rows.some(

                    row =>

                        row
                            ?.image_categories

                        ||

                        row
                            ?.blog_categories
                );

            return hasCategory

                ? "Kategorie"

                : null;
        },

        /*
        |--------------------------------------------------------------------------
        | Get Checked
        |--------------------------------------------------------------------------
        */

        async getChecked(id) {

            try {

                const response =
                    await axios.get(

                        `/api/getCheckedDone/${id}`
                    );

                return (
                    response.data.done
                    === true
                );

            } catch (error) {

                console.error(

                    "Fehler beim Abrufen des Status:",

                    error
                );

                return false;
            }
        },

        /*
        |--------------------------------------------------------------------------
        | Has Created
        |--------------------------------------------------------------------------
        */

        async checkhasCreated() {

            try {

                const response =
                    await axios.get(

                        `/hasCreated/${this.table}`
                    );

                this.hasCreated =
                    response.data;

            } catch (error) {

                console.error(

                    "Fehler bei hasCreated:",

                    error
                );

                this.hasCreated = false;
            }
        },
    },
});
</script>
    <style>
    td {
        white-space: normal;
        word-wrap: break-word;
        overflow-wrap: break-word;
    }
    .wwr {
        word-wrap: break-word;
        overflow-wrap: break-word;
        white-space: normal;
    }
    .oton {
        background-color: rgb(50, 174, 179);
        border-radius: 50%;
        width: 24px !important;
        height: 24px;
        padding: 0px 3px;
        color: #fff;
    }
    .np-dl-th-normal {
        margin-left: 8px;
    }
    </style>

